#include <bits/stdc++.h>
using namespace std;

vector<int> readIntArray(const string& s) {
    vector<int> arr;
    stringstream ss(s);
    int num;
    while (ss >> num) {
        arr.push_back(num);
    }
    return arr;
}

class Cutting {
public:
    bool isBalanced(const vector<int>& array, int index) {
        int evenCount = 0, oddCount = 0;
        for (int i = 0; i <= index; i++) {
            if (array[i] % 2 == 0) evenCount++;
            else oddCount++;
        }
        return evenCount == oddCount;
    }

    int findCutPosition(const vector<int>& array, int coins, unordered_set<int>& used) {
        int position = -1;
        int minCost = coins + 1;
        for (int i = 1; i < (int)array.size() - 1; i++) {
            int cost = abs(array[i] - array[i + 1]);
            if (cost < minCost && isBalanced(array, i) && used.find(i) == used.end()) {
                minCost = cost;
                position = i;
            }
        }
        return position;
    }

    int getMaximumCuts(int n, int b, const vector<int>& a) {
        int remainingCoins = b;
        int totalCuts = 0;
        unordered_set<int> usedIndices;
        while (remainingCoins > 0) {
            int cutPos = findCutPosition(a, remainingCoins, usedIndices);
            if (cutPos >= 0) {
                usedIndices.insert(cutPos);
                int cost = abs(a[cutPos] - a[cutPos + 1]);
                remainingCoins -= cost;
                totalCuts++;
            } else {
                break;
            }
        }
        return totalCuts;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line1, line2;
    getline(cin, line1);
    getline(cin, line2);
    vector<int> nb = readIntArray(line1);
    vector<int> a = readIntArray(line2);
    int n = nb[0];
    int b = nb[1];
    Cutting c;
    cout << c.getMaximumCuts(n, b, a) << "\n";
    return 0;
}

